// Sea Ice Extent — Time Series, route: jsx
// Source: sea-ice-extent-1978-2017
//
// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from seaIce ----
type SeaIcePoint = { date: Date; value: number };
type SeaIceYear = { year: number; values: SeaIcePoint[] };

const FIRST_YEAR = 1978;
const YEAR_COUNT = 40;
const SAMPLE_STEP = 7; // weekly samples
const PEAK_DAY = 65; // northern-hemisphere maximum falls in early March

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(19781026);

/** Every year is projected onto a single common year so the 40 curves overlay. */
const dayDate = (day: number) => new Date(Date.UTC(2000, 0, 1) + day * 86400000);

/**
 * Synthetic, not NSIDC: a seasonal cosine whose September minimum falls roughly
 * 2.5x faster than its March maximum, which is the shape of the real record.
 */
const seaIceYears: SeaIceYear[] = Array.from({ length: YEAR_COUNT }, (_, i) => {
  const maximum = 16.1 - 0.028 * i;
  const minimum = 7.5 - 0.07 * i;
  const middle = (maximum + minimum) / 2;
  const amplitude = (maximum - minimum) / 2;
  const yearOffset = (random() - 0.5) * 0.5;
  const lastDay = i === YEAR_COUNT - 1 ? 245 : 364; // the final year is still in progress

  let drift = 0;
  const values: SeaIcePoint[] = [];
  for (let day = 0; day <= lastDay; day += SAMPLE_STEP) {
    drift = drift * 0.75 + (random() - 0.5) * 0.12;
    const seasonal = Math.cos((2 * Math.PI * (day - PEAK_DAY)) / 365);
    values.push({ date: dayDate(day), value: middle + amplitude * seasonal + yearOffset + drift });
  }
  return { year: FIRST_YEAR + i, values };
});

const LAST_YEAR = FIRST_YEAR + YEAR_COUNT - 1;

const MARGIN = { top: 68, right: 46, bottom: 44, left: 46 };
const DRAW_STAGGER = 0.07;
const GRADIENT_ID = 'sea-ice-year-gradient';

const YEAR_DOMAIN: [Date, Date] = [new Date(Date.UTC(2000, 0, 1)), new Date(Date.UTC(2000, 11, 31))];

/** One entry per year, oldest first, each carrying that year's samples in date order. */
export type Data = { year: number; values: { date: Date; value: number }[] }[];

export default function SeaIceExtent({
  data = seaIceYears,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.max(300, Math.round(width * 0.62));
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const firstYear = data[0].year;
  const lastYear = data[data.length - 1].year;

  const x = useMemo(
    () => d3.scaleUtc().domain(YEAR_DOMAIN).range([0, innerWidth]),
    [innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (s) => d3.max(s.values, (d) => d.value) ?? 0) ?? 0])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleSequential<string>([firstYear, lastYear], (t) => d3.interpolateSpectral(1 - t)),
    [firstYear, lastYear]
  );

  const series = useMemo(() => {
    const line = d3
      .line<SeaIcePoint>()
      .x((d) => x(d.date))
      .y((d) => y(d.value));
    return data.map((s) => {
      const last = s.values[s.values.length - 1];
      return {
        year: s.year,
        path: line(s.values) ?? '',
        endX: x(last.date),
        endY: y(last.value)
      };
    });
  }, [data, x, y]);

  const xTicks: Tick[] = useMemo(() => {
    const months = d3.utcMonths(YEAR_DOMAIN[0], YEAR_DOMAIN[1]);
    const step = Math.ceil(months.length / Math.max(3, Math.floor(innerWidth / 68)));
    return months
      .filter((_, i) => i % step === 0)
      .map((v) => ({ value: d3.utcFormat('%b')(v), offset: x(v) }));
  }, [x, innerWidth]);

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: String(v), offset: y(v) })),
    [y]
  );

  // Sampled stops stand in for the continuous sequential scale in the legend bar.
  const legendStops = useMemo(
    () =>
      d3.range(11).map((i) => ({
        offset: `${i * 10}%`,
        color: color(firstYear + (i / 10) * (lastYear - firstYear))
      })),
    [color, firstYear, lastYear]
  );

  if (width === 0) return null;

  const legendWidth = Math.max(60, Math.min(180, innerWidth - 70));
  const labelled = [series[0], series[series.length - 1]];

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      // role="img" makes the aria-label replace the inner text, so the "synthetic" caption
      // below would never reach a screen reader unless it is repeated here.
      aria-label={`Forty yearly curves of synthetic northern-hemisphere sea ice extent, ${firstYear} to ${lastYear}, each coloured by year and overlaid on a shared day-of-year axis. Generated data, not NSIDC observations.`}
    >
      <defs>
        <linearGradient id={GRADIENT_ID} x1="0" x2="1" y1="0" y2="0">
          {legendStops.map((s) => (
            <stop key={s.offset} offset={s.offset} stopColor={s.color} />
          ))}
        </linearGradient>
      </defs>

      <g transform={`translate(${MARGIN.left},12)`}>
        <text y={8} dy="0.32em" fill="var(--muted)" fontSize={11}>
          Year
        </text>
        <g transform="translate(34,0)">
          <rect width={legendWidth} height={8} fill={`url(#${GRADIENT_ID})`} rx={1} />
          <text y={22} fill="var(--muted)" fontSize={10}>
            {firstYear}
          </text>
          <text x={legendWidth} y={22} textAnchor="end" fill="var(--muted)" fontSize={10}>
            {lastYear}
          </text>
        </g>
      </g>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <text x={-MARGIN.left} y={-10} fill="var(--muted)" fontSize={11}>
          ↑ Sea ice extent (million km²)
        </text>

        {series.map((s, i) => (
          <motion.path
            key={s.year}
            d={s.path}
            fill="none"
            stroke={color(s.year)}
            strokeWidth={1.1}
            strokeLinejoin="round"
            strokeLinecap="round"
            strokeMiterlimit={1}
            initial={{ pathLength: 0 }}
            animate={{ pathLength: 1 }}
            transition={{ duration: 0.5, delay: i * DRAW_STAGGER, ease: 'linear' }}
          />
        ))}

        {/* Only the first and last year get direct labels; forty would collide. */}
        {labelled.map((s, i) => (
          <motion.text
            key={s.year}
            x={s.endX + 4}
            y={s.endY}
            dy="0.32em"
            fill={color(s.year)}
            fontSize={11}
            paintOrder="stroke"
            stroke="var(--bg)"
            strokeWidth={3}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{
              duration: 0.3,
              delay: (i === 0 ? 0 : series.length - 1) * DRAW_STAGGER + 0.5
            }}
          >
            {s.year}
          </motion.text>
        ))}
      </g>

      {width >= 320 && (
        <text x={MARGIN.left} y={height - 6} fill="var(--muted)" fontSize={10}>
          Synthetic seeded data, not NSIDC observations.
        </text>
      )}
    </svg>
  );
}
